function cheapColumn(q){if(![-3,-2,-1,0].every(y=>full(bot.blockAt(q.offset(0,y,0)))))return false;if(!dirs.every(d=>[-2,-1].every(y=>full(bot.blockAt(q.plus(d).offset(0,y,0))))))return false;const hasPick=bot.inventory.items().some(i=>i.name.endsWith('_pickaxe'));return [0,-1,-2].every(y=>{const n=bot.blockAt(q.offset(0,y,0)).name;return ['grass_block','dirt'].includes(n)||(hasPick&&['stone','granite','diorite','andesite','sandstone'].includes(n))||(n==='sand'&&bot.inventory.items().some(i=>stableNames.includes(i.name)))});}
function contactThreat(){const eye=bot.entity.position.offset(0,1.62,0);return foes().find(e=>{if(Math.abs(e.position.y-bot.entity.position.y)>3&&!['skeleton','stray','witch'].includes(e.name))return false;const r=['skeleton','stray','witch'].includes(e.name)?16:e.name==='creeper'?13:10;if(e.position.distanceTo(bot.entity.position)>r)return false;const v=e.position.offset(0,1.2,0).minus(eye);return !bot.world.raycast(eye,v.unit(),v.norm())});}
async function centerDrop(q){await tick(5);await center(q);await tick(4);for(const a of ['x','z'])if(bot.entity.position[a]<q[a]+.33||bot.entity.position[a]>q[a]+.67)throw Error('DROP_CENTER_POST');}
async function immediateBurial(reason){life();bot.pathfinder.setGoal(null);bot.clearControlStates();for(let k=0;k<12&&!bot.entity.onGround;k++)await tick(1);const q=bot.entity.position.floored().offset(0,-1,0);if(bot.entity.isInWater||[0,1].some(y=>['water','bubble_column'].includes(bot.blockAt(bot.entity.position.floored().offset(0,y,0))?.name))||!bot.entity.onGround||!cheapColumn(q))return false;await centerDrop(q);if(!cheapColumn(q))return false;global.P1DownPending={feet:q.offset(0,-2,0),roof:q,at:Date.now()};let steps=0;try{for(let y=0;y>=-2;y--){life();const b=bot.blockAt(q.offset(0,y,0)),pick=bot.inventory.items().find(i=>i.name.endsWith('_pickaxe'));if(pick&&!['dirt','grass_block','sand'].includes(b.name))await bot.equip(pick,'hand');else await bot.unequip('hand');await bot.dig(b,true);steps++;for(let k=0;k<35&&(!bot.entity.onGround||Math.abs(bot.entity.position.y-q.y-y)>.12);k++)await tick(1);if(!bot.entity.onGround||Math.abs(bot.entity.position.y-q.y-y)>.12)throw Error('BURIAL_SETTLE')}for(let k=0;k<30&&!bot.inventory.items().some(i=>stableNames.includes(i.name));k++)await tick(1);const item=bot.inventory.items().find(i=>stableNames.includes(i.name));if(!item)throw Error('BURIAL_NO_CAP');await bot.equip(item,'hand');const rd=dirs.find(d=>full(bot.blockAt(q.plus(d))));if(!rd)throw Error('BURIAL_NO_ANCHOR');await bot._placeBlockWithOptions(bot.blockAt(q.plus(rd)),rd.scaled(-1),{forceLook:true});await tick(4);if(!shell(q.offset(0,-2,0)))throw Error('BURIAL_HULL');const inside=foes().filter(e=>Math.abs(e.position.x-q.x-.5)<.85&&Math.abs(e.position.z-q.z-.5)<.85&&e.position.y>=q.y-2.5&&e.position.y<q.y);if(inside.length)throw Error('BURIAL_OCCUPIED_'+inside.map(e=>e.name));global.P1Overland=global.P1DownPending;global.P1DownPending=null;console.log('IN_PROGRAM_BURIAL_VERIFIED',reason,bot.entity.position,bot.health);return true;}catch(e){console.log('BURIAL_ERROR',steps,e.message,JSON.stringify({q,p:bot.entity.position,ground:bot.entity.onGround,v:bot.entity.vel